input.command:
mkdir -p /tmp/nshtest/home /tmp/nshtest/wd /workspace/notes
cat > /tmp/nshtest/run.sh <<'EOF'
#!/bin/bash
# usage: run.sh [--cols N] [--rows N] [--cwd DIR] [--home DIR] [--timeout T] [--extra 'args'] <<< directives
COLS=80; ROWS=24; CWD=/tmp/nshtest/wd; HOMEDIR=/tmp/nshtest/home; TMO=6; EXTRA="--norc"
while [ $# -gt 0 ]; do
  case "$1" in
    --cols) COLS=$2; shift 2;;
    --rows) ROWS=$2; shift 2;;
    --cwd) CWD=$2; shift 2;;
    --home) HOMEDIR=$2; shift 2;;
    --timeout) TMO=$2; shift 2;;
    --extra) EXTRA="$2"; shift 2;;
    *) break;;
  esac
done
python3 /workspace/tools/pty_run.py --cols "$COLS" --rows "$ROWS" --timeout "$TMO" \
  --cwd "$CWD" --env HOME="$HOMEDIR" -- /workspace/executable $EXTRA
EOF
chmod +x /tmp/nshtest/run.sh
echo ok
